	public static string getVersion()
	{
		Assembly executingAssembly = Assembly.GetExecutingAssembly();
		string text = "." + (executingAssembly.GetName().Version.Build).ToString() + "." + (executingAssembly.GetName().Version.Revision).ToString();
		return " (dll " + executingAssembly.GetName().Version.Major.ToString() + "." + (executingAssembly.GetName().Version.Minor + text) + ")";
	}
